import ownedStyles0 from '../../components/DemoLayout.module.css';
import { componentClasses } from '../../class-names';
import { useId, useState } from 'react';
import { BusinessDemo } from '../../components/BusinessDemo';
import { Field } from '../../components/Field';
import { AnimatedSelect } from '../../components/AnimatedSelect';

const ownedStyles={...ownedStyles0};
const cn=(names:string)=>componentClasses(ownedStyles,names);
export default function BusinessCascadeSelectDemo() {
  const groups = [{ label: '研发', teams: [{ label: '界面组', members: ['林清', '周远'] }, { label: '平台组', members: ['陈宁', '许安'] }] }, { label: '服务', teams: [{ label: '支持组', members: ['赵禾', '沈言'] }] }];
  const [department, setDepartment] = useState(/*__AW_STATE_state.department__*/);
  const [team, setTeam] = useState(/*__AW_STATE_state.team__*/);
  const [member, setMember] = useState(/*__AW_STATE_state.member__*/);
  const prefix = useId();
  const teams = groups.find(item => item.label === department)?.teams ?? [];
  const members = teams.find(item => item.label === team)?.members ?? [];
  return <BusinessDemo title="CascadeSelect" description="按区域、团队、成员三级联动选择；弹性下拉保持各级状态清晰。">
    <div data-ui="aw-business-grid" className={cn("aw-business-grid")}>
      <Field  htmlFor={`${prefix}-department`} /*__AW_PROPS_t0__*/ ><AnimatedSelect id={`${prefix}-department`}   value={department}  onChange={value => { setDepartment(value); setTeam(''); setMember(''); }} /*__AW_PROPS_t1__*/  /></Field>
      <Field  htmlFor={`${prefix}-team`} /*__AW_PROPS_t2__*/ ><AnimatedSelect id={`${prefix}-team`}   disabled={!department} value={team} options={teams.map(item => item.label)} onChange={value => { setTeam(value); setMember(''); }} /*__AW_PROPS_t3__*/  /></Field>
      <Field  htmlFor={`${prefix}-member`} /*__AW_PROPS_t4__*/ ><AnimatedSelect id={`${prefix}-member`}   disabled={!team} value={member} options={members} onChange={setMember} /*__AW_PROPS_t5__*/  /></Field>
    </div><p data-ui="aw-business-status" className={cn("aw-business-status")} role="status">{member ? `${department} / ${team} / ${member}` : '请选择完整的层级。'}</p>
  </BusinessDemo>;
}
